import { get_product_details } from "@/graphql/queries.js";
import { API, graphqlOperation } from "aws-amplify";
import EditProduct from "@/components/CRM/Popups/EditProduct.vue";
import SnackBar from "@/components/SnackBar.vue";
export default {
  components: {
    EditProduct,
    SnackBar
  },
  data() {
    return {
      product_name: "",
      product_description: "",
      userselect: "",
      userArray: [],
      componentcheck: 0,
      contactnumber: "",
      SnackBarComponent: {},
      domainUrl: "",
      searchF: "",
      editdetails: {},
      height: 0,
      loading: false,
      adminemail: "",
      product_status: "",
      producttype: "",
      product_ticket_raise: "",
      noOfCampagins: "",
      noOfUpcomingCampaigns: "",
      noOfLiveCampaigns: "",
      noOfCompletedCampaigns: ""
    };
  },
  created() {
    this.height = window.innerHeight - 310;
    this.get_product();
  },
  methods: {
    async get_product() {
      this.tableLoading = true;
      try {
        let result = await API.graphql(graphqlOperation(get_product_details, {
          input: {
            product_id: this.$store.getters.Getproductitems.product_id
          }
        }));
        this.tableLoading = false;
        var response = result.data.get_product_details.items[0];
        var admin = JSON.parse(result.data.get_product_details.items[0].admin_details);
        this.editdetails = response;
        this.product_name = response.product_name;
        this.product_description = response.product_description;
        this.producttype = response.product_type;
        this.userselect = admin.full_user_name;
        this.product_status = response.product_status;
        this.adminemail = admin.user_email_id;
        this.product_ticket_raise = response.product_ticket_raise;
        this.domainUrl = response.product_domain_url == null ? "" : response.product_domain_url;
        this.contactnumber = admin.user_full_contact_number;
        this.noOfCampagins = response.no_of_campaigns == null ? 0 : response.no_of_campaigns;
        this.noOfUpcomingCampaigns = response.no_upcoming_campaigns == null ? 0 : response.no_upcoming_campaigns;
        this.noOfLiveCampaigns = response.no_live_campaigns == null ? 0 : response.no_live_campaigns;
        this.noOfCompletedCampaigns = response.no_completed_campaigns == null ? 0 : response.no_completed_campaigns;
      } catch (error) {
        this.tableLoading = false;
        this.SnackBarComponent = {
          SnackbarVmodel: true,
          SnackbarColor: "red",
          SnackbarText: error.errors[0].message,
          timeout: 5000,
          Top: true
        };
      }
    },
    edit_mutation() {
      this.editdetails;
      this.componentcheck = 1;
      this.producteditdetails = true;
    },
    success_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "green",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
      this.get_product();
      this.producteditdetails = false;
    },
    error_info(val) {
      this.SnackBarComponent = {
        SnackbarVmodel: true,
        SnackbarColor: "red",
        SnackbarText: val,
        timeout: 5000,
        Top: true
      };
    }
  }
};
